// RUNWAY — how long the money lasts, and it is reported on the LOW band.
//
// This is the number people act on, so it is the one most worth getting pessimistic. A runway
// computed on expected income says "eleven months" and is right on average and useless in the case
// that matters: the case where income comes in low is exactly the case where you needed to know.
// All three scenarios are computed; `headline` is `low`, and that choice is the module's position
// rather than a default somebody can drift away from.
//
// TWO THINGS THAT ARE UNKNOWN, NOT ZERO, and both would silently lengthen the runway:
//
//  1. DISCRETIONARY SPENDING. The obligation calendar knows rent and subscriptions. It does not know
//     groceries, fuel, or a haircut. A runway from obligations alone is not conservative — it is
//     wrong in the flattering direction. So `discretionary` is a REQUIRED argument: passing zero is
//     allowed and is a decision that gets said out loud in the problems list.
//  2. MONTHS PAST THE CALENDAR. Beyond the calendar's window there are no known obligations, so
//     costs would read as zero and the runway would extend forever on nothing. The horizon is
//     TRUNCATED to what the calendar actually covers, and truncating is stated.
import { type Money, money, add, subtract, scale } from "@/features/finance/lib/money";
import type { Position } from "@/features/finance/lib/position";
import type { IncomeProjection, MonthBand } from "@/features/finance/lib/projection";
import { type ObligationCalendar, monthTotal, monthsBetween } from "@/features/finance/lib/obligations";

export type Scenario = "low" | "expected" | "high";

export interface RunwayMonth {
  readonly month: string;
  /** Liquid at the start of the month. */
  readonly opening: Money;
  readonly income: Money;
  readonly obligations: Money;
  readonly discretionary: Money;
  /** income − obligations − discretionary. */
  readonly net: Money;
  readonly closing: Money;
  /** POSITIVE amount the month ends short by, when it ends short. */
  readonly shortfall?: Money;
}

export interface RunwayResult {
  readonly scenario: Scenario;
  readonly months: readonly RunwayMonth[];
  /** The FIRST month that ends below zero. Not the worst one — the first. */
  readonly exhaustsIn?: string;
  /** WHOLE months survived before that. Undefined when the horizon is survived outright. */
  readonly monthsOfCover?: number;
  /** The lowest closing balance anywhere in the horizon, which can be later than exhaustion. */
  readonly tightest?: RunwayMonth;
  /** The smallest constant monthly amount that would keep every month above zero. */
  readonly monthlyGap: Money;
}

export interface Runway {
  readonly asOf: string;
  readonly currency: string;
  /** LIQUID only. An investment is not runway, and net worth is not money you can spend. */
  readonly startingLiquid: Money;
  readonly low: RunwayResult;
  readonly expected: RunwayResult;
  readonly high: RunwayResult;
  /** The one to plan on. It is `low`, deliberately. */
  readonly headline: RunwayResult;
  /** How far the horizon actually reaches, after truncation. */
  readonly through?: string;
  readonly problems: readonly string[];
  readonly provenance: string;
}

export interface RunwayOptions {
  /**
   * Everything the calendar cannot see: groceries, fuel, transport, the ordinary week. REQUIRED, so
   * it cannot be forgotten — a runway that quietly assumes zero is the flattering kind of wrong.
   */
  readonly discretionary: Money;
}

const bandValue = (b: MonthBand, s: Scenario): Money => (s === "low" ? b.low : s === "high" ? b.high : b.expected);

function walk(
  months: readonly MonthBand[],
  calendar: ObligationCalendar,
  start: Money,
  discretionary: Money,
  scenario: Scenario,
  currency: string,
): RunwayResult {
  const out: RunwayMonth[] = [];
  let balance = start;
  for (const band of months) {
    const income = bandValue(band, scenario);
    const obligations = monthTotal(calendar, band.month, currency);
    const net = subtract(subtract(income, obligations), discretionary);
    const opening = balance;
    const closing = add(opening, net);
    balance = closing;
    out.push({
      month: band.month,
      opening,
      income,
      obligations,
      discretionary,
      net,
      closing,
      ...(closing.minor < 0 ? { shortfall: money(-closing.minor, currency) } : {}),
    });
  }

  // THE FIRST month that ends short, not the worst one. Income can be lumpy enough that a later
  // month is deeper underwater, but the month you run out of money is the month you run out.
  const firstShort = out.findIndex((m) => m.closing.minor < 0);
  const tightest = out.length
    ? out.reduce((worst, m) => (m.closing.minor < worst.closing.minor ? m : worst))
    : undefined;

  // Adding x per month raises month i's closing by x·(i+1), so the smallest x that clears every
  // month is the largest per-month share of any deficit. Exact, not searched for.
  const need = out.reduce((mx, m, i) => Math.max(mx, m.closing.minor < 0 ? -m.closing.minor / (i + 1) : 0), 0);

  return {
    scenario,
    months: out,
    ...(firstShort >= 0 ? { exhaustsIn: out[firstShort].month, monthsOfCover: firstShort } : {}),
    ...(tightest ? { tightest } : {}),
    monthlyGap: money(Math.ceil(need), currency),
  };
}

export function runway(
  position: Position,
  projection: IncomeProjection,
  calendar: ObligationCalendar,
  opts: RunwayOptions,
): Runway {
  const { discretionary } = opts;
  const currency = position.currency;
  const problems: string[] = [...position.problems];

  const empty = (scenario: Scenario): RunwayResult => ({ scenario, months: [], monthlyGap: money(0, currency) });
  const refuse = (reason: string): Runway => ({
    asOf: position.asOf,
    currency,
    startingLiquid: position.liquid,
    low: empty("low"),
    expected: empty("expected"),
    high: empty("high"),
    headline: empty("low"),
    problems: [...problems, reason],
    provenance: position.provenance,
  });

  if (!projection.projectable) {
    return refuse(`no runway without an income projection: ${projection.reason}`);
  }
  if (discretionary.currency !== currency) {
    return refuse(`discretionary spending is in ${discretionary.currency} but the position is in ${currency}`);
  }

  // TRUNCATE to what the calendar covers. Past its window there are no known obligations, so every
  // month beyond would read as costing nothing and the runway would extend on the strength of a gap
  // in the data.
  const covered = new Set(monthsBetween(calendar.from, calendar.to));
  const months = projection.months.filter((b) => covered.has(b.month));
  if (months.length < projection.months.length) {
    problems.push(
      `the obligation calendar stops at ${calendar.to}, so the runway is cut to ${months.length} of ${projection.months.length} projected month(s) — beyond it nothing is known to be due, which is not the same as nothing being due`,
    );
  }
  if (!months.length) {
    return refuse(`the obligation calendar (${calendar.from}..${calendar.to}) covers none of the projected months`);
  }
  if (discretionary.minor === 0) {
    problems.push(
      "discretionary spending was given as zero — this runway assumes groceries, fuel and everything else outside the standing obligations cost nothing, which nobody's does",
    );
  }
  if (!position.complete) {
    problems.push("the position under this runway is incomplete, so every figure here inherits whatever it could not account for");
  }

  const low = walk(months, calendar, position.liquid, discretionary, "low", currency);

  return {
    asOf: position.asOf,
    currency,
    startingLiquid: position.liquid,
    low,
    expected: walk(months, calendar, position.liquid, discretionary, "expected", currency),
    high: walk(months, calendar, position.liquid, discretionary, "high", currency),
    // THE HEADLINE IS THE LOW BAND. A runway on expected income is right on average and useless in
    // the case that matters, because the case where income comes in low is the case you needed it.
    headline: low,
    through: months[months.length - 1].month,
    problems,
    provenance: position.provenance,
  };
}

/** Whether the horizon is survived outright under a scenario. */
export const survivesHorizon = (r: RunwayResult): boolean => r.exhaustsIn === undefined && r.months.length > 0;

/** What a year of the headline gap costs to close. Often the more legible framing of `monthlyGap`. */
export const annualGap = (r: Runway): Money => scale(r.headline.monthlyGap, 12);

/** One sentence a person can act on, in the terms they asked the question in. */
export function summarise(r: Runway): string {
  const h = r.headline;
  if (!h.months.length) return `no runway could be computed — ${r.problems[r.problems.length - 1] ?? "not enough is known"}`;
  if (survivesHorizon(h)) {
    return `on the LOW income band the money holds through ${r.through}, tightest at ${h.tightest!.month} with ${h.tightest!.closing.minor} minor units left`;
  }
  return `on the LOW income band the money runs out in ${h.exhaustsIn} — ${h.monthsOfCover} whole month(s) of cover; ${h.monthlyGap.minor} minor units more per month would close it`;
}

