import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import type { Position } from "@/features/finance/lib/position";
import type { IncomeProjection, MonthBand } from "@/features/finance/lib/projection";
import { buildCalendar, type ObligationCalendar } from "@/features/finance/lib/obligations";
import type { Recurring } from "@/features/finance/lib/recurring";
import { annualGap, runway, summarise, survivesHorizon } from "@/features/finance/lib/runway";

// SYNTHETIC FIXTURES ONLY. No real statement, balance or account number belongs in this repo.
const usd = (major: number): Money => fromMajor(major, "USD");

const band = (month: string, low: number, expected: number, high: number): MonthBand => ({
  month,
  low: usd(low),
  expected: usd(expected),
  high: usd(high),
});

const projection = (months: MonthBand[]): IncomeProjection => ({
  projectable: true,
  months,
  total: { low: usd(0), expected: usd(0), high: usd(0) },
  assumptions: [],
  excluded: [],
  sourcesUsed: 1,
});

const position = (liquid: number, over: Partial<Position> = {}): Position => ({
  asOf: "2026-06-30",
  currency: "USD",
  accounts: [],
  netWorth: usd(liquid),
  liquid: usd(liquid),
  totalDebt: usd(0),
  dailyInterest: usd(0),
  minimumsDue: usd(0),
  complete: true,
  problems: [],
  provenance: "reconciled · synthetic",
  ...over,
});

/** Rent every month, so the calendar has something real in it. */
const rent = (major: number): Recurring => ({
  key: "rent",
  label: "RENT",
  account: "checking",
  cadence: "monthly",
  typical: usd(major),
  annualised: usd(major * 12),
  occurrences: 6,
  firstSeen: "2026-01-01",
  lastSeen: "2026-06-01",
  regularity: 1,
  amountStability: 1,
  lapsed: false,
});

const calendar = (major: number, to = "2026-12-31"): ObligationCalendar =>
  buildCalendar([rent(major)], undefined, { from: "2026-07-01", to });

const SIX = ["2026-07", "2026-08", "2026-09", "2026-10", "2026-11", "2026-12"].map((m) =>
  band(m, 2000, 3000, 3500),
);

describe("runway — the headline is the LOW band", () => {
  it("plans on low, not on expected", () => {
    // A runway on expected income is right on average and useless in the case that matters: the
    // case where income comes in low is exactly the case you needed the number for.
    const r = runway(position(3000), projection(SIX), calendar(2500), { discretionary: usd(600) });
    expect(r.headline).toBe(r.low);
    expect(r.headline.scenario).toBe("low");
    // Low runs out; expected does not. Reporting the wrong one is the whole failure.
    expect(r.low.exhaustsIn).toBeDefined();
    expect(survivesHorizon(r.expected)).toBe(true);
    expect(survivesHorizon(r.high)).toBe(true);
  });

  it("computes all three so the spread is visible", () => {
    const r = runway(position(3000), projection(SIX), calendar(2500), { discretionary: usd(600) });
    expect(r.low.months[0].income.minor).toBe(usd(2000).minor);
    expect(r.expected.months[0].income.minor).toBe(usd(3000).minor);
    expect(r.high.months[0].income.minor).toBe(usd(3500).minor);
  });

  it("starts from LIQUID, never from net worth", () => {
    // An investment is not runway. Starting from net worth would say the money lasts years.
    const p = position(3000, { netWorth: usd(80_000) });
    const r = runway(p, projection(SIX), calendar(2500), { discretionary: usd(600) });
    expect(r.startingLiquid.minor).toBe(usd(3000).minor);
    expect(r.low.months[0].opening.minor).toBe(usd(3000).minor);
  });
});

describe("runway — the arithmetic", () => {
  const r = () => runway(position(3000), projection(SIX), calendar(2500), { discretionary: usd(600) });

  it("carries the closing balance into the next month's opening", () => {
    const ms = r().low.months;
    for (let i = 1; i < ms.length; i++) expect(ms[i].opening.minor).toBe(ms[i - 1].closing.minor);
  });

  it("nets income against obligations AND discretionary", () => {
    const m = r().low.months[0];
    expect(m.income.minor).toBe(usd(2000).minor);
    expect(m.obligations.minor).toBe(usd(2500).minor);
    expect(m.discretionary.minor).toBe(usd(600).minor);
    expect(m.net.minor).toBe(usd(-1100).minor);
    expect(m.closing.minor).toBe(usd(1900).minor);
  });

  it("counts WHOLE months survived — a month that ends short is not one of them", () => {
    // 3000 → 1900 → 800 → −300. Two whole months of cover, and the third is where it runs out.
    const res = r().low;
    expect(res.monthsOfCover).toBe(2);
    expect(res.exhaustsIn).toBe("2026-09");
    expect(res.months[2].shortfall!.minor).toBe(usd(300).minor);
    expect(res.months[1].shortfall).toBeUndefined();
  });

  it("reports the FIRST month that ends short, not the worst one", () => {
    const res = r().low;
    expect(res.exhaustsIn).toBe("2026-09");
    // The worst month is the last one, four months later. Reporting that as the runway would say
    // there are five months of cover when there are two.
    expect(res.tightest!.month).toBe("2026-12");
    expect(res.tightest!.closing.minor).toBeLessThan(res.months[2].closing.minor);
  });

  it("says exactly how much more per month would close it", () => {
    const res = r().low;
    // Adding x per month raises month i's closing by x·(i+1); the binding month is the one with the
    // largest per-month share of its deficit.
    const gap = res.monthlyGap.minor;
    expect(gap).toBeGreaterThan(0);
    const patched = runway(
      position(3000),
      projection(SIX.map((b) => ({ ...b, low: usd(2000 + gap / 100) }))),
      calendar(2500),
      { discretionary: usd(600) },
    );
    expect(survivesHorizon(patched.low)).toBe(true);
    expect(annualGap(r()).minor).toBe(gap * 12);
  });

  it("survives outright when income covers the outgoings", () => {
    const res = runway(position(3000), projection(SIX), calendar(1000), { discretionary: usd(600) }).low;
    expect(survivesHorizon(res)).toBe(true);
    expect(res.exhaustsIn).toBeUndefined();
    expect(res.monthsOfCover).toBeUndefined();
    expect(res.monthlyGap.minor).toBe(0);
  });
});

describe("runway — what is unknown is not zero", () => {
  it("TRUNCATES at the obligation calendar, rather than running on a gap in the data", () => {
    // Beyond the calendar nothing is known to be due, so every month past it would cost zero and the
    // runway would extend on the strength of missing data.
    const r = runway(position(3000), projection(SIX), calendar(2500, "2026-09-30"), { discretionary: usd(600) });
    expect(r.low.months.map((m) => m.month)).toEqual(["2026-07", "2026-08", "2026-09"]);
    expect(r.through).toBe("2026-09");
    expect(r.problems.join(" ")).toContain("not the same as nothing being due");
  });

  it("refuses when the calendar covers none of the projected months", () => {
    const r = runway(position(3000), projection(SIX), calendar(2500, "2026-06-30"), { discretionary: usd(600) });
    expect(r.low.months).toEqual([]);
    expect(r.headline.months).toEqual([]);
    expect(r.problems.join(" ")).toContain("covers none of the projected months");
    expect(summarise(r)).toContain("no runway could be computed");
  });

  it("says out loud that a zero discretionary figure was a decision", () => {
    const r = runway(position(3000), projection(SIX), calendar(1000), { discretionary: usd(0) });
    expect(r.problems.join(" ")).toContain("nobody's does");
  });

  it("refuses without an income projection rather than assuming none", () => {
    const none: IncomeProjection = {
      projectable: false,
      reason: "2 whole month(s) of history",
      months: [],
      assumptions: [],
      excluded: [],
      sourcesUsed: 0,
    };
    const r = runway(position(3000), none, calendar(2500), { discretionary: usd(600) });
    expect(r.low.months).toEqual([]);
    expect(r.problems.join(" ")).toContain("2 whole month(s) of history");
  });

  it("carries the position's own problems forward instead of starting clean", () => {
    const p = position(3000, { complete: false, problems: ["'savings' is declared but has no balance"] });
    const r = runway(p, projection(SIX), calendar(1000), { discretionary: usd(600) });
    expect(r.problems.join(" ")).toContain("'savings' is declared but has no balance");
    expect(r.problems.join(" ")).toContain("inherits whatever it could not account for");
  });

  it("refuses a discretionary figure in another currency", () => {
    const r = runway(position(3000), projection(SIX), calendar(1000), { discretionary: fromMajor(500, "EUR") });
    expect(r.low.months).toEqual([]);
    expect(r.problems.join(" ")).toContain("EUR");
  });
});

describe("summarise", () => {
  it("says when it runs out and what would close it", () => {
    const s = summarise(runway(position(3000), projection(SIX), calendar(2500), { discretionary: usd(600) }));
    expect(s).toContain("LOW income band");
    expect(s).toContain("2026-09");
    expect(s).toContain("2 whole month(s) of cover");
  });

  it("says when it holds, and where it is tightest", () => {
    const s = summarise(runway(position(3000), projection(SIX), calendar(1000), { discretionary: usd(600) }));
    expect(s).toContain("holds through 2026-12");
    expect(s).toContain("tightest at");
  });
});
